def find_content_children_brute(g, s):
    n, m = len(g), len(s)
    best = 0
    for mask in range(1 << m):                              # try every subset of cookies used
        used_children = set()
        cookies_used = [s[j] for j in range(m) if mask & (1 << j)]
        for cookie in sorted(cookies_used, reverse=True):
            for i in range(n):
                if i not in used_children and cookie >= g[i]:
                    used_children.add(i)
                    break
        best = max(best, len(used_children))
    return best

