import java.util.*;

public class Main {
    static int findContentChildren(int[] g, int[] s) {
        Arrays.sort(g);
        Arrays.sort(s);
        int i = 0, j = 0;
        while (i < g.length && j < s.length) {
            if (s[j] >= g[i]) i++;                // this cookie satisfies the current child
            j++;                                    // always move to the next cookie
        }
        return i;
    }
}

